-- Deteccion de necesidades, plan anual, cursos, participantes, costos y resultados.
create table if not exists public.hr_training_needs(
 id uuid primary key default gen_random_uuid(),need_year integer not null check(need_year between 2020 and 2100),employee_id uuid references public.hr_employees(id),direction_name text not null default '',department_name text not null default '',source text not null default 'MANUAL' check(source in('MANUAL','DESEMPENO','PLAN_MEJORA','UNIDAD')),
 performance_evaluation_id uuid references public.hr_performance_evaluations(id),topic text not null,description text not null default '',priority text not null default 'MEDIA' check(priority in('BAJA','MEDIA','ALTA','CRITICA')),status text not null default 'DETECTADA' check(status in('DETECTADA','PLANIFICADA','ATENDIDA','CANCELADA')),
 detected_by uuid not null references public.app_users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create table if not exists public.hr_training_plans(
 id uuid primary key default gen_random_uuid(),plan_year integer not null unique check(plan_year between 2020 and 2100),name text not null,budget_amount numeric(18,2) not null default 0 check(budget_amount>=0),status text not null default 'BORRADOR' check(status in('BORRADOR','APROBADO','EN_EJECUCION','CERRADO')),
 objectives text not null default '',approved_by uuid references public.app_users(id),approved_at timestamptz,created_by uuid not null references public.app_users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create table if not exists public.hr_training_courses(
 id uuid primary key default gen_random_uuid(),plan_id uuid not null references public.hr_training_plans(id),need_id uuid references public.hr_training_needs(id),course_code bigint generated always as identity,title text not null,provider text not null default '',modality text not null default 'PRESENCIAL' check(modality in('PRESENCIAL','VIRTUAL','HIBRIDA')),
 start_date date not null,end_date date not null,hours numeric(8,2) not null default 0 check(hours>=0),planned_cost numeric(18,2) not null default 0 check(planned_cost>=0),actual_cost numeric(18,2) not null default 0 check(actual_cost>=0),capacity integer not null default 0 check(capacity>=0),status text not null default 'PLANIFICADO' check(status in('PLANIFICADO','CONVOCADO','EN_CURSO','FINALIZADO','CANCELADO')),
 created_by uuid not null references public.app_users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(end_date>=start_date)
);
create table if not exists public.hr_training_participants(
 id uuid primary key default gen_random_uuid(),course_id uuid not null references public.hr_training_courses(id) on delete cascade,employee_id uuid not null references public.hr_employees(id),attendance_percent numeric(5,2) not null default 0 check(attendance_percent between 0 and 100),learning_score numeric(5,2) check(learning_score between 0 and 100),result text not null default 'INSCRITO' check(result in('INSCRITO','APROBADO','REPROBADO','AUSENTE','RETIRADO')),
 certificate_name text not null default '',certificate_url text not null default '',certificate_date date,observations text not null default '',registered_by uuid not null references public.app_users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(course_id,employee_id)
);
create index if not exists hr_training_needs_year_idx on public.hr_training_needs(need_year,status,priority);create index if not exists hr_training_courses_plan_idx on public.hr_training_courses(plan_id,status,start_date);create index if not exists hr_training_participants_employee_idx on public.hr_training_participants(employee_id,created_at desc);
alter table public.hr_training_needs enable row level security;alter table public.hr_training_plans enable row level security;alter table public.hr_training_courses enable row level security;alter table public.hr_training_participants enable row level security;
revoke all on public.hr_training_needs,public.hr_training_plans,public.hr_training_courses,public.hr_training_participants from anon,authenticated;

create or replace function public.list_hr_training(p_token text,p_year integer)
returns jsonb language plpgsql security definer set search_path=public,extensions as $$declare v_user public.app_users;begin v_user:=public.hr_authenticated_user(p_token);if v_user.id is null or (v_user.role<>'Administrador' and not coalesce((v_user.permissions->>'ver_recursos_humanos')::boolean,false)) then return jsonb_build_object('success',false,'error','No posee permiso para consultar capacitación.');end if;
 return jsonb_build_object('success',true,
 'employees',coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'employee_code',e.employee_code,'full_name',e.full_name,'position_name',e.position_name,'direction_name',e.direction_name,'department_name',e.department_name) order by e.full_name) from public.hr_employees e where e.employment_status<>'Desvinculado' and (v_user.role='Administrador' or public.hr_employee_in_user_scope(v_user,e))),'[]'::jsonb),
 'needs',coalesce((select jsonb_agg(to_jsonb(x) order by case x.priority when 'CRITICA' then 1 when 'ALTA' then 2 when 'MEDIA' then 3 else 4 end,x.created_at desc) from(select n.*,e.employee_code,e.full_name,e.position_name from public.hr_training_needs n left join public.hr_employees e on e.id=n.employee_id where n.need_year=p_year and (n.employee_id is null or v_user.role='Administrador' or public.hr_employee_in_user_scope(v_user,e)))x),'[]'::jsonb),
 'plans',coalesce((select jsonb_agg(to_jsonb(p) order by p.plan_year desc) from public.hr_training_plans p where p.plan_year=p_year),'[]'::jsonb),
 'courses',coalesce((select jsonb_agg(to_jsonb(x) order by x.start_date,x.title) from(select c.*,n.topic need_topic,(select count(*) from public.hr_training_participants t where t.course_id=c.id) participant_count,(select count(*) from public.hr_training_participants t where t.course_id=c.id and t.result='APROBADO') approved_count,coalesce((select round(avg(t.attendance_percent),2) from public.hr_training_participants t where t.course_id=c.id),0) average_attendance,coalesce((select round(avg(t.learning_score),2) from public.hr_training_participants t where t.course_id=c.id),0) average_learning from public.hr_training_courses c join public.hr_training_plans p on p.id=c.plan_id left join public.hr_training_needs n on n.id=c.need_id where p.plan_year=p_year)x),'[]'::jsonb),
 'participants',coalesce((select jsonb_agg(to_jsonb(x) order by x.full_name,x.title) from(select t.*,e.employee_code,e.full_name,e.position_name,c.title,c.start_date,c.end_date,c.hours from public.hr_training_participants t join public.hr_employees e on e.id=t.employee_id join public.hr_training_courses c on c.id=t.course_id join public.hr_training_plans p on p.id=c.plan_id where p.plan_year=p_year and (v_user.role='Administrador' or public.hr_employee_in_user_scope(v_user,e)))x),'[]'::jsonb),
 'indicators',(select jsonb_build_object('planned_courses',count(*),'completed_courses',count(*) filter(where c.status='FINALIZADO'),'planned_cost',coalesce(sum(c.planned_cost),0),'actual_cost',coalesce(sum(c.actual_cost),0),'participants',coalesce(sum((select count(*) from public.hr_training_participants t where t.course_id=c.id)),0),'approved',coalesce(sum((select count(*) from public.hr_training_participants t where t.course_id=c.id and t.result='APROBADO')),0),'average_attendance',coalesce(round(avg((select avg(t.attendance_percent) from public.hr_training_participants t where t.course_id=c.id)),2),0)) from public.hr_training_courses c join public.hr_training_plans p on p.id=c.plan_id where p.plan_year=p_year));end $$;

create or replace function public.manage_hr_training(p_token text,p_action text,p_data jsonb)
returns jsonb language plpgsql security definer set search_path=public,extensions as $$declare v_user public.app_users;v_id uuid;v_plan uuid;v_need public.hr_training_needs;v_participant public.hr_training_participants;begin v_user:=public.hr_authenticated_user(p_token);if v_user.id is null or (v_user.role<>'Administrador' and not coalesce((v_user.permissions->>'editar_recursos_humanos')::boolean,false)) then return jsonb_build_object('success',false,'error','No posee permiso para gestionar capacitación.');end if;
 if p_action='NECESIDAD' then insert into public.hr_training_needs(need_year,employee_id,direction_name,department_name,source,performance_evaluation_id,topic,description,priority,detected_by) values((p_data->>'year')::integer,nullif(p_data->>'employee_id','')::uuid,trim(coalesce(p_data->>'direction_name','')),trim(coalesce(p_data->>'department_name','')),coalesce(nullif(p_data->>'source',''),'MANUAL'),nullif(p_data->>'performance_evaluation_id','')::uuid,trim(p_data->>'topic'),trim(coalesce(p_data->>'description','')),upper(coalesce(nullif(p_data->>'priority',''),'MEDIA')),v_user.id) returning id into v_id;
 elsif p_action='PLAN' then insert into public.hr_training_plans(plan_year,name,budget_amount,objectives,created_by) values((p_data->>'year')::integer,trim(p_data->>'name'),coalesce((p_data->>'budget_amount')::numeric,0),trim(coalesce(p_data->>'objectives','')),v_user.id) on conflict(plan_year) do update set name=excluded.name,budget_amount=excluded.budget_amount,objectives=excluded.objectives,updated_at=now() returning id into v_id;
 elsif p_action='APROBAR_PLAN' then if v_user.role<>'Administrador' and not coalesce((v_user.permissions->>'aprobar_recursos_humanos')::boolean,false) then return jsonb_build_object('success',false,'error','No posee permiso para aprobar el plan.');end if;update public.hr_training_plans set status='APROBADO',approved_by=v_user.id,approved_at=now(),updated_at=now() where id=(p_data->>'plan_id')::uuid returning id into v_id;
 elsif p_action='CURSO' then select id into v_plan from public.hr_training_plans where plan_year=(p_data->>'year')::integer;if v_plan is null then return jsonb_build_object('success',false,'error','Primero debe crear el plan anual.');end if;insert into public.hr_training_courses(plan_id,need_id,title,provider,modality,start_date,end_date,hours,planned_cost,capacity,created_by) values(v_plan,nullif(p_data->>'need_id','')::uuid,trim(p_data->>'title'),trim(coalesce(p_data->>'provider','')),upper(coalesce(nullif(p_data->>'modality',''),'PRESENCIAL')),(p_data->>'start_date')::date,(p_data->>'end_date')::date,coalesce((p_data->>'hours')::numeric,0),coalesce((p_data->>'planned_cost')::numeric,0),coalesce((p_data->>'capacity')::integer,0),v_user.id) returning id into v_id;update public.hr_training_needs set status='PLANIFICADA',updated_at=now() where id=nullif(p_data->>'need_id','')::uuid;
 elsif p_action='PARTICIPANTE' then insert into public.hr_training_participants(course_id,employee_id,registered_by) values((p_data->>'course_id')::uuid,(p_data->>'employee_id')::uuid,v_user.id) on conflict(course_id,employee_id) do nothing returning id into v_id;if v_id is null then return jsonb_build_object('success',false,'error','El empleado ya está inscrito en el curso.');end if;
 elsif p_action='RESULTADO' then update public.hr_training_participants set attendance_percent=(p_data->>'attendance_percent')::numeric,learning_score=nullif(p_data->>'learning_score','')::numeric,result=upper(p_data->>'result'),observations=trim(coalesce(p_data->>'observations','')),updated_at=now() where id=(p_data->>'participant_id')::uuid returning * into v_participant;v_id:=v_participant.id;
 elsif p_action='CERTIFICADO' then update public.hr_training_participants set certificate_name=trim(p_data->>'certificate_name'),certificate_url=trim(p_data->>'certificate_url'),certificate_date=coalesce(nullif(p_data->>'certificate_date','')::date,current_date),updated_at=now() where id=(p_data->>'participant_id')::uuid returning id into v_id;
 elsif p_action='FINALIZAR_CURSO' then update public.hr_training_courses set status='FINALIZADO',actual_cost=coalesce((p_data->>'actual_cost')::numeric,0),updated_at=now() where id=(p_data->>'course_id')::uuid returning need_id,id into v_plan,v_id;update public.hr_training_needs set status='ATENDIDA',updated_at=now() where id=v_plan;
 else return jsonb_build_object('success',false,'error','Acción de capacitación inválida.');end if;insert into public.security_audit_log(actor_user_id,action,module,detail) values(v_user.id,'CAPACITACION_'||p_action,'Recursos Humanos',p_data||jsonb_build_object('result_id',v_id));return jsonb_build_object('success',true,'id',v_id);end $$;
grant execute on function public.list_hr_training(text,integer),public.manage_hr_training(text,text,jsonb) to anon,authenticated;
